(5708511, 828897, 44877, '<td valign="top">Wow - that''s some gorgeous.</td>', 'Wow - that''s some gorgeous.', '2009-11-01 10:10:05.000000', NULL, 1),
(5708515, 830807, 98022, '<td valign="top">Nice autumn shot. I like how the diagonal lines pull you in to the photo. Good DOF.</td>', 'Nice autumn shot. I like how the diagonal lines pull you in to the photo. Good DOF.', '2009-11-01 10:12:40.000000', NULL, 1),
(5708518, 830036, 98022, '<td valign="top">Very nice macro.</td>', 'Very nice macro.', '2009-11-01 10:12:58.000000', NULL, 1),
(5708521, 829913, 23484, '<td valign="top">Very nice colors and reflections.</td>', 'Very nice colors and reflections.', '2009-11-01 10:14:39.000000', NULL, 1),
(5708523, 829855, 23484, '<td valign="top">A little too dark but nice image.</td>', 'A little too dark but nice image.', '2009-11-01 10:15:16.000000', NULL, 1),
(5708524, 830068, 65234, '<td valign="top">Love the composition.  Looks a bit flat, lightwise.  I''d shoot with a graduated ND filter to get more color in the sky (or use a gradient filter in PP), bump up the saturation and contrast, and do some selective dodging to bring out more detail (especially in the foliage and along the path to lead my eye through the shot).  Or try HDR, if you have an HDR program.  There''s a lot here to like, it just feels like it could use a bit of jazzing up to make it extraordinary.</td>', 'Love the composition.  Looks a bit flat, lightwise.  I''d shoot with a graduated ND filter to get more color in the sky (or use a gradient filter in PP), bump up the saturation and contrast, and do some selective dodging to bring out more detail (especially in the foliage and along the path to lead my eye through the shot).  Or try HDR, if you have an HDR program.  There''s a lot here to like, it just feels like it could use a bit of jazzing up to make it extraordinary.', '2009-11-01 10:15:49.000000', NULL, 1),
(5708526, 827297, 23484, '<td valign="top">Neat shot. Nice colors</td>', 'Neat shot. Nice colors', '2009-11-01 10:16:19.000000', NULL, 1),
