INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5709147, 830303, 30982, '<td valign="top">Heh!  You almost had me convinced until I saw the Starbucks sign.  :-)  Perhaps a bit oversharpened but I do like the toning and all the competing lines.  The foreground bike works, too - would have been even better if you''d kept that whole back tire in the frame.  Lots going on, but I like that.</td>', 'Heh!  You almost had me convinced until I saw the Starbucks sign.  :-)  Perhaps a bit oversharpened but I do like the toning and all the competing lines.  The foreground bike works, too - would have been even better if you''d kept that whole back tire in the frame.  Lots going on, but I like that.', '2009-11-01 15:58:22.000000', NULL, 1),
