INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5713233, 830320, 101117, '<td valign="top">Interesting shot, by my initial impression was that his head is a little low in the frame, there''s too little of the main subject to see. I like your background detail, so I think perhaps a little less cropped off the bottom and this would be a lot better.</td>', 'Interesting shot, by my initial impression was that his head is a little low in the frame, there''s too little of the main subject to see. I like your background detail, so I think perhaps a little less cropped off the bottom and this would be a lot better.', '2009-11-04 05:56:38.000000', NULL, 1),
(5713234, 829775, 101117, '<td valign="top">I think this had the potential to be a really good shot, but the processing has left lots of odd details in the shots, the most noticeable of which is that her left arm looks like it''s covered in hair!<br/> <br/>With a slightly different processing technique and less glow round the left of the shot this would be a lot better.</td>', 'I think this had the potential to be a really good shot, but the processing has left lots of odd details in the shots, the most noticeable of which is that her left arm looks like it''s covered in hair! With a slightly different processing technique and less glow round the left of the shot this would be a lot better.', '2009-11-04 05:58:30.000000', NULL, 1),
(5713237, 829935, 101117, '<td valign="top">Nice enough shot with good colours, but not really much to hold my attention.</td>', 'Nice enough shot with good colours, but not really much to hold my attention.', '2009-11-04 05:59:15.000000', NULL, 1),
(5713242, 830672, 101117, '<td valign="top">Brave entry for the free study! The minute this one opened I was taken aback, while there''s nothing obviously interesting in this scene, I actually find the shot very interesting indeed. I find myself staring into that large black square in the middle of the frame, then to the door and then back again. Very interesting!</td>', 'Brave entry for the free study! The minute this one opened I was taken aback, while there''s nothing obviously interesting in this scene, I actually find the shot very interesting indeed. I find myself staring into that large black square in the middle of the frame, then to the door and then back again. Very interesting!', '2009-11-04 06:04:09.000000', NULL, 1),
(5713243, 830525, 101117, '<td valign="top">Nice picturesque scene with good colours. I like the way the top of the clouds / mist is catching the reflection of the sky. Processing might just be a touch over the top, which has left the clouds looking a bit jagged.</td>', 'Nice picturesque scene with good colours. I like the way the top of the clouds / mist is catching the reflection of the sky. Processing might just be a touch over the top, which has left the clouds looking a bit jagged.', '2009-11-04 06:05:18.000000', NULL, 1),
(5713246, 827422, 101117, '<td valign="top">Very "Old England" look to this, which is probably because that''s exactly what it is. My first thought was Winchester, but I don''t think that''s Winchester Cathedral, so I''m probably wrong.<br/> <br/>The processing you have applied to this has given it a bit of a "drawing" look, which isn''t necessarily a bad thing for this scene.</td>', 'Very "Old England" look to this, which is probably because that''s exactly what it is. My first thought was Winchester, but I don''t think that''s Winchester Cathedral, so I''m probably wrong. The processing you have applied to this has given it a bit of a "drawing" look, which isn''t necessarily a bad thing for this scene.', '2009-11-04 06:08:50.000000', NULL, 1),
(5713247, 830497, 101117, '<td valign="top">I like the brown leaves in the background, this shot says "fall" very well.</td>', 'I like the brown leaves in the background, this shot says "fall" very well.', '2009-11-04 06:09:22.000000', NULL, 1),
(5713248, 830593, 101117, '<td valign="top">Your lighting, while even, is very harsh. The light colours are almost sore to look at. Nice enough model shot despite that though.</td>', 'Your lighting, while even, is very harsh. The light colours are almost sore to look at. Nice enough model shot despite that though.', '2009-11-04 06:10:24.000000', NULL, 1),
(5713249, 830757, 101117, '<td valign="top">This just feels like a bit of a snapshot of the pumpkin rather than anything photographic (if you see what I mean). Very nicely carved pumpkin though!</td>', 'This just feels like a bit of a snapshot of the pumpkin rather than anything photographic (if you see what I mean). Very nicely carved pumpkin though!', '2009-11-04 06:12:04.000000', NULL, 1),
(5713252, 830061, 101117, '<td valign="top">I think your DOF might be a little too narrow. The sharp part seems almost detached from the rest and because of the angle it''s sitting at, isn''t particularly interesting.<br/> <br/>I think the colours also aren''t helping here, there''s not a whole lot of contrast in the entire scene, but it''s not really soft enough to take it down that path either.</td>', 'I think your DOF might be a little too narrow. The sharp part seems almost detached from the rest and because of the angle it''s sitting at, isn''t particularly interesting. I think the colours also aren''t helping here, there''s not a whole lot of contrast in the entire scene, but it''s not really soft enough to take it down that path either.', '2009-11-04 06:13:46.000000', NULL, 1),
(5713253, 830811, 101117, '<td valign="top">Very nice autumn scene, love the colours. Not sure if that''s a path running off into the distance or just a clearing, would be nice to have something to lead the eye into the scene though.</td>', 'Very nice autumn scene, love the colours. Not sure if that''s a path running off into the distance or just a clearing, would be nice to have something to lead the eye into the scene though.', '2009-11-04 06:14:46.000000', NULL, 1),
(5713254, 830280, 101117, '<td valign="top">Very different look to autumn in this shot. I like the barrenness of it all, the toning helps that feeling along, and the clouds just top it off. Nicely done.</td>', 'Very different look to autumn in this shot. I like the barrenness of it all, the toning helps that feeling along, and the clouds just top it off. Nicely done.', '2009-11-04 06:15:52.000000', NULL, 1),
(5713262, 830482, 101117, '<td valign="top">Love the lighting and shadow here, and the really interesting main subject. All the other aspects (the barren grass, the pale blue sky) compliment the subject nicely, well done!</td>', 'Love the lighting and shadow here, and the really interesting main subject. All the other aspects (the barren grass, the pale blue sky) compliment the subject nicely, well done!', '2009-11-04 06:19:39.000000', NULL, 1),
(5713263, 825796, 101117, '<td valign="top">Ha, well caught, that would be an interesting ride!</td>', 'Ha, well caught, that would be an interesting ride!', '2009-11-04 06:20:13.000000', NULL, 1),
(5713264, 830736, 101117, '<td valign="top">Very nice strong colours, the sky is completely overpowering the shot, which isn''t a bad thing here as it''s clearly the subject with the mountains becoming secondary. Nice reflection as well.</td>', 'Very nice strong colours, the sky is completely overpowering the shot, which isn''t a bad thing here as it''s clearly the subject with the mountains becoming secondary. Nice reflection as well.', '2009-11-04 06:21:22.000000', NULL, 1),
