INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5715050, 830351, 39850, '<td valign="top">6 - Whilst this is interesting with the person widely straddled on the left - the person in front of the lighthouse looks in quite a predicament.  If the quality was there - a specific crop on this part of the scene would make a fantastic image/capture/photograph.  Some tweaking in post processing too, just to bring out the depth a little more and also clone out the couple of specks on the right.  Your call of course, but the title detracts/doesn''t seem to suit the image.</td>', '6 - Whilst this is interesting with the person widely straddled on the left - the person in front of the lighthouse looks in quite a predicament.  If the quality was there - a specific crop on this part of the scene would make a fantastic image/capture/photograph.  Some tweaking in post processing too, just to bring out the depth a little more and also clone out the couple of specks on the right.  Your call of course, but the title detracts/doesn''t seem to suit the image.', '2009-11-05 06:57:41.000000', NULL, 1),
