(5716916, 827524, 101117, '<td valign="top">Nice flower shot, I like the contrast in colours between the red foreground flower and the yellow background ones.</td>', 'Nice flower shot, I like the contrast in colours between the red foreground flower and the yellow background ones.', '2009-11-06 19:59:52.000000', NULL, 1),
(5716921, 828488, 101117, '<td valign="top">This is a little messy for my tastes and the colours aren''t particularly pleasing. I do like the separation between the foreground branches and the background forest, it feels like they are a sort of fence or net, but overall not a shot that appeals to me.</td>', 'This is a little messy for my tastes and the colours aren''t particularly pleasing. I do like the separation between the foreground branches and the background forest, it feels like they are a sort of fence or net, but overall not a shot that appeals to me.', '2009-11-06 20:01:44.000000', NULL, 1),
(5716925, 829319, 101117, '<td valign="top">It''s scenes like this that make me wish I was back in Europe. Very nice colours and light, great mood to this shot.</td>', 'It''s scenes like this that make me wish I was back in Europe. Very nice colours and light, great mood to this shot.', '2009-11-06 20:03:10.000000', NULL, 1),
(5716928, 830656, 101117, '<td valign="top">Nice flower macro, I like the depth of field you have here, shallow but enough to be able to take in the flower while still giving it a nice softness.</td>', 'Nice flower macro, I like the depth of field you have here, shallow but enough to be able to take in the flower while still giving it a nice softness.', '2009-11-06 20:04:49.000000', NULL, 1),
(5716933, 830332, 101117, '<td valign="top">Interesting portrait. There''s something a bit unusual that makes this stand out from the other portraits, though I''m not entirely sure what it is!</td>', 'Interesting portrait. There''s something a bit unusual that makes this stand out from the other portraits, though I''m not entirely sure what it is!', '2009-11-06 20:06:57.000000', NULL, 1),
