(5716953, 830267, 65234, '<td valign="top">I''m not letting a little drool fool me; those eyes look wise beyond her months!  Gorgeous portrait.</td>', 'I''m not letting a little drool fool me; those eyes look wise beyond her months!  Gorgeous portrait.', '2009-11-06 20:28:39.000000', NULL, 1),
(5716954, 830760, 101117, '<td valign="top">Nice colours in the foreground. I like the way you have used the city as the background and had it less dominant, makes a nice change from the strong skylines.</td>', 'Nice colours in the foreground. I like the way you have used the city as the background and had it less dominant, makes a nice change from the strong skylines.', '2009-11-06 20:30:03.000000', NULL, 1),
