(5716979, 827547, 101117, '<td valign="top">Nice bug macro, great details and a nice matching blurred background.</td>', 'Nice bug macro, great details and a nice matching blurred background.', '2009-11-06 20:48:46.000000', NULL, 1),
(5716981, 830511, 101117, '<td valign="top">He looks like a swan with attitude! <br/> <br/>You have a very red hue across this shot, not sure if it was intentional as it''s very obvious, but I don''t think it helps at all.</td>', 'He looks like a swan with attitude!  You have a very red hue across this shot, not sure if it was intentional as it''s very obvious, but I don''t think it helps at all.', '2009-11-06 20:49:37.000000', NULL, 1),
