(5718182, 830639, 101117, '<td valign="top">Nice close-up / macro. The really vivid yellow colours are slightly overexposed, but I don''t think that''s actually a bad thing here and it adds to the vibrancy of the shot. I like the way the pattern repeats into the background.</td>', 'Nice close-up / macro. The really vivid yellow colours are slightly overexposed, but I don''t think that''s actually a bad thing here and it adds to the vibrancy of the shot. I like the way the pattern repeats into the background.', '2009-11-07 22:03:10.000000', NULL, 1),
(5718184, 830285, 101117, '<td valign="top">Fun and expressive self portrait! Good detail and lighting which is something I''ve never really been able to manage in a self portrait.</td>', 'Fun and expressive self portrait! Good detail and lighting which is something I''ve never really been able to manage in a self portrait.', '2009-11-07 22:06:02.000000', NULL, 1),
(5718186, 830259, 106349, '<td valign="top">You did a great job capturing emotion in this shot! This is one of my high votes.</td>', 'You did a great job capturing emotion in this shot! This is one of my high votes.', '2009-11-07 22:06:46.000000', NULL, 1),
