(5718239, 829406, 76335, '<td valign="top">Beautifully seen and composed. Abstract and graphic, but it still comes across as an effective still life. One of my top picks, easily. A nine for you.</td>', 'Beautifully seen and composed. Abstract and graphic, but it still comes across as an effective still life. One of my top picks, easily. A nine for you.', '2009-11-07 23:31:26.000000', NULL, 1),
(5718242, 826340, 76335, '<td valign="top">Too blurry to freeze any real sports action, but not blurry enough to be abstract. As such, the eye is drawn to the more sharply rendered spectators (who probably could have been cropped out).</td>', 'Too blurry to freeze any real sports action, but not blurry enough to be abstract. As such, the eye is drawn to the more sharply rendered spectators (who probably could have been cropped out).', '2009-11-07 23:35:00.000000', NULL, 1),
(5718244, 830682, 76335, '<td valign="top">I''m not sure what makes her hell''s bride. It''s an effective composition though.</td>', 'I''m not sure what makes her hell''s bride. It''s an effective composition though.', '2009-11-07 23:36:52.000000', NULL, 1),
(5718246, 829671, 76335, '<td valign="top">The DOF flattens the scene nicely to show off some good radial geometry. Nice!</td>', 'The DOF flattens the scene nicely to show off some good radial geometry. Nice!', '2009-11-07 23:37:45.000000', NULL, 1),
(5718247, 828845, 76335, '<td valign="top">Beautifully abstract, and I love the cool blue tones.</td>', 'Beautifully abstract, and I love the cool blue tones.', '2009-11-07 23:38:15.000000', NULL, 1),
(5718251, 830587, 41337, '<td valign="top">What a quirky image.</td>', 'What a quirky image.', '2009-11-07 23:39:38.000000', NULL, 1),
(5718254, 830674, 76335, '<td valign="top">Very nicely done except that her face looks a little strained, unnatural -- like perhaps she''s uncomfortable. It''s most obvious in the eyes and brows.</td>', 'Very nicely done except that her face looks a little strained, unnatural -- like perhaps she''s uncomfortable. It''s most obvious in the eyes and brows.', '2009-11-07 23:41:35.000000', NULL, 1),
